   "default": null,
   "constraints": []
  },
  {
   "name": "delete",
   "type": "boolean",
   "required": false,
   "description": "Filter groups by whether they are deleted or not.",
   "default": false,
   "constraints": []
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1.0, <= 9.223372036854776e+18"
   ]
  }
 ],
 "response_schemas": {
  "success": [
   {
    "group_id": 1,
